<script setup lang="ts">
import AuthenticatedLayout from "@/Layouts/AuthenticatedLayout.vue"; import { Head, Link, router } from "@inertiajs/vue3"; import { ref, watch } from "vue"; import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"; import { Button } from "@/components/ui/button"; import { Input } from "@/components/ui/input"; import { Badge } from "@/components/ui/badge"; import { IconPlus, IconPencil, IconPower } from "@tabler/icons-vue";
defineOptions({ layout: AuthenticatedLayout }); const props=defineProps<{gudangs:any;filters:{search?:string}}>(); const search=ref(props.filters.search||""); let timeout:ReturnType<typeof setTimeout>; watch(search,v=>{clearTimeout(timeout);timeout=setTimeout(()=>router.get(route('gudang.index'),{search:v},{preserveState:true,replace:true}),400)});
